-- 007: importa o catálogo completo (planilha 'Catálogo - Painel de controle', abas Catálogo + FICHAS)
-- 84 modelos ativos, cores unificadas (20 novas), preços atacado/varejo, foto, ficha técnica e SKUs da grade.
-- A marcação 'dv' do catálogo (fotos de estúdio) NÃO é cor e ficou de fora.
alter table public.produtos add column if not exists ficha jsonb;

insert into public.cores (empresa_id, nome, sigla, hex) select e.id, c.nome, c.sigla, c.hex from public.empresas e, (values
('Azul Aqua','AQU','#7FC8C8'),('Canela','CAN','#9C5B34'),('Capuccino','CAP','#8E6B53'),('Conhaque','CON','#8A3F1F'),
('Couro','COU','#8B5A2B'),('Verde Esmeralda','ESM','#1F6F55'),('Azul Hydra / Caramelo','HCA','#5E6E5E'),
('Azul Hydra / Nude / Cortiça','HNC','#7E8A80'),('Azul Hydra','HYD','#2E6E8E'),('Verde Mint','MIN','#BFE3D0'),
('Marsala','MRS','#7B2D35'),('Nude / Off-White','NOF','#E6D3BE'),('Nude Pedra','NPE','#D2B79E'),
('Natural / Whisky','NWH','#C9A27A'),('Off Carvalho','OCA','#CDB596'),('Off-White / Whisky','OWH','#D8BFA0'),
('Rosa BB','RBB','#F2C9D2'),('Rum','RUM','#6B3A26'),('Terra','TER','#9A5A3C'),('Vanila','VAN','#F1E3A8')
) as c(nome,sigla,hex) where e.slug='dbaesse' on conflict do nothing;

