create temp table _p on commit drop as
select x->>0 as ref, x->>1 as nome, x->>2 as tipo, (x->>3)::int as de, (x->>4)::int as ate,
       (x->>5)::numeric as atac, (x->>6)::numeric as var,
       'https://raw.githubusercontent.com/leonardonandes-cmyk/Imagens-Cat-logo-/main/' || (x->>7) as foto,
       (select j->'f'->((x->>8)::int) from _cat) as ficha, x->>9 as cores
from _cat, jsonb_array_elements(_cat.j->'p') x;

insert into public.produtos (empresa_id, ref, nome, tipo, grade_de, grade_ate, preco_atacado, preco_varejo, foto_url, ficha, status)
select e.id, p.ref, p.nome, p.tipo, p.de, p.ate, p.atac, p.var, p.foto, p.ficha, 'ativo'
from _p p, public.empresas e where e.slug = 'dbaesse'
on conflict (empresa_id, ref) do update set nome = excluded.nome, tipo = excluded.tipo, grade_de = excluded.grade_de,
  grade_ate = excluded.grade_ate, preco_atacado = excluded.preco_atacado, preco_varejo = excluded.preco_varejo,
  foto_url = excluded.foto_url, ficha = excluded.ficha, status = 'ativo';

insert into public.skus (empresa_id, produto_id, cor_id, numero, sku)
select pr.empresa_id, pr.id, c.id, n, pr.ref || '-' || c.sigla || '-' || n
from _p p
join public.produtos pr on pr.ref = p.ref
cross join lateral unnest(string_to_array(p.cores, ' ')) as s(sigla)
join public.cores c on c.empresa_id = pr.empresa_id and c.sigla = s.sigla
cross join lateral generate_series(pr.grade_de, pr.grade_ate) n
on conflict do nothing;
